#!/usr/bin/env bash
# lab-check.sh - checks the whole lab FROM THE OUTSIDE, like a user would:
# internal DNS, SSH port of every node, Gitea over HTTPS, certificate expiry.
# Runs on the bastion only. Deployed by Ansible (role "maintenance"), cron every 15 min.
#
# Config:     /etc/homelab/lab-check.conf (generated by Ansible from the inventory)
# Exit codes: 0 = all OK, 1 = at least one warning, 2 = missing tool
# Log:        /var/log/homelab/lab-check.log  (+ syslog, tag "lab-check", warnings only)
# Manual run: sudo /usr/local/bin/lab-check.sh
set -euo pipefail

CONF=${CONF:-/etc/homelab/lab-check.conf}
LOG_DIR=${LOG_DIR:-/var/log/homelab}
LOG_FILE="$LOG_DIR/lab-check.log"
TAG=lab-check
warnings=0

# shellcheck source=/dev/null
source "$CONF"   # DNS_SERVER, DOMAIN, NODES, GITEA_URL, CERT_HOST, CERT_WARN_DAYS

log() {   # usage: log LEVEL message...
    local level=$1
    shift
    printf '%s %s %-4s %s\n' "$(date -Is)" "$(hostname -s)" "$level" "$*" | tee -a "$LOG_FILE"
    if [[ $level != OK ]]; then
        logger -t "$TAG" -p user.warning -- "$level $*" || true
    fi
}

warn() {
    log WARN "$@"
    warnings=$((warnings + 1))
}

mkdir -p "$LOG_DIR"

# 0. Required tools - a missing tool must not look like a broken lab
for cmd in dig curl openssl timeout; do
    if ! command -v "$cmd" >/dev/null; then
        log ERR "required command '$cmd' not found - install it first"
        exit 2
    fi
done

# 1. Internal DNS answers with the expected IP, and every node's SSH port is open
for entry in $NODES; do            # entry = name=ip
    name=${entry%%=*}
    ip=${entry#*=}
    answer=$(dig +short +time=2 +tries=1 "$name.$DOMAIN" "@$DNS_SERVER" 2>/dev/null | head -n 1 || true)
    if [[ $answer != "$ip" ]]; then
        warn "DNS $name.$DOMAIN -> '${answer:-no answer}', expected $ip"
    fi
    if ! timeout 3 bash -c "</dev/tcp/$ip/22" 2>/dev/null; then
        warn "SSH port 22 on $name ($ip) not reachable"
    fi
done

# 2. Gitea answers over HTTPS (200 or a redirect to the login page)
code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 "$GITEA_URL" || true)
if [[ ! $code =~ ^(2|3)[0-9][0-9]$ ]]; then
    warn "Gitea $GITEA_URL returned HTTP ${code:-none}"
fi

# 3. Certificate expiry (acme.sh should renew ~30 days before expiry)
end_date=$(echo | openssl s_client -connect "$CERT_HOST:443" -servername "$CERT_HOST" 2>/dev/null \
    | openssl x509 -noout -enddate 2>/dev/null | cut -d= -f2 || true)
if [[ -z $end_date ]]; then
    warn "could not read the TLS certificate of $CERT_HOST"
else
    days_left=$(( ( $(date -d "$end_date" +%s) - $(date +%s) ) / 86400 ))
    if (( days_left < CERT_WARN_DAYS )); then
        warn "certificate of $CERT_HOST expires in $days_left days (threshold $CERT_WARN_DAYS)"
    fi
fi

if (( warnings == 0 )); then
    log OK "DNS, SSH, Gitea HTTPS fine; certificate valid for ${days_left} more days"
    exit 0
fi
exit 1
